import app from 'flarum/common/app';
import Component from 'flarum/common/Component';
import Alert from 'flarum/common/components/Alert';
import Button from 'flarum/common/components/Button';
import { messageKind } from '../messageKind';
import { uiIcon } from '../uiIcons';
// Анкета и окно над ней могут показывать одно состояние. У одного сообщения
// остаётся одно уведомление, пока существует хотя бы одно место его показа.
const active = new Map();

/** Только стандартные компоненты Flarum: Alert в форме или app.alerts для сбоев.
 * Показ выполняется в lifecycle, никогда не при каждом вызове view().
 */
export default class Feedback extends Component {
  notification = '';
  messages() {
    return [...new Set((Array.isArray(this.attrs.message) ? this.attrs.message : [this.attrs.message]).filter(Boolean))];
  }
  kind(message) {
    return this.attrs.kind ?? messageKind(message);
  }
  errors() {
    return this.attrs.inline || this.attrs.hint ? [] : this.messages().filter(message => this.kind(message) !== 'input');
  }
  sync() {
    const errors = this.errors(),
      key = JSON.stringify(errors);
    if (this.notification === key) return;
    this.release();
    if (!errors.length) return;
    this.notification = key;
    const existing = active.get(key);
    if (existing) existing.owners.add(this);else active.set(key, {
      id: app.alerts.show({
        type: 'error',
        role: 'alert',
        controls: this.controls
      }, errors.join('\n')),
      owners: new Set([this])
    });
  }
  release() {
    const entry = active.get(this.notification);
    if (entry) {
      entry.owners.delete(this);
      if (!entry.owners.size) {
        app.alerts.dismiss(entry.id);
        active.delete(this.notification);
      }
    }
    this.notification = '';
  }
  oncreate() {
    this.sync();
  }
  onupdate() {
    this.sync();
  }
  onremove() {
    this.release();
  }
  view(vnode) {
    const refresh = this.attrs.refresh;
    this.controls = refresh ? [m(Button, {
      type: "button",
      className: "Button Button--link Button--icon RpFeedback-refresh",
      icon: uiIcon('actions.refresh'),
      title: refresh.label,
      "aria-label": refresh.label,
      disabled: refresh.disabled,
      onclick: () => this.attrs.refresh?.run()
    })] : vnode.children;
    const messages = this.messages();
    if (this.attrs.hint) return m("p", {
      className: "helpText"
    }, messages.join(' '));
    const warnings = messages.filter(message => this.attrs.inline || this.kind(message) === 'input');
    if (!warnings.length) return m("span", {
      hidden: true
    });
    const type = this.attrs.inline && messages.some(message => this.kind(message) !== 'input') ? 'error' : 'warning';
    return m(Alert, {
      type: type,
      role: "alert",
      dismissible: false,
      controls: this.controls
    }, warnings.length === 1 ? warnings[0] : m("ul", null, warnings.map(message => m("li", {
      key: message
    }, message))));
  }
}
flarum.reg.add('maxcuso-roleplay', 'common/components/Feedback', Feedback);