import Modal from '../../../common/components/RoleplayModal';
import Button from 'flarum/common/components/Button';
/** Шаблон — копия существующего определения перка; отдельного типа или признака не появляется. */
export default class CatalogTemplateModal extends Modal {
  selected = '';
  modalClassName() {
    return 'RpCatalogTemplate';
  }
  modalHeading() {
    return {
      label: 'Создание перка из шаблона',
      purpose: 'create'
    };
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("label", null, "\u041F\u0435\u0440\u043A \u0434\u043B\u044F \u043A\u043E\u043F\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u044F", m("select", {
      className: "FormControl",
      value: this.selected,
      onchange: event => this.selected = event.target.value
    }, [m("option", {
      key: "empty",
      value: ""
    }, "\u0412\u044B\u0431\u0435\u0440\u0438 \u043F\u0435\u0440\u043A"), ...this.attrs.rows.map(row => m("option", {
      key: row.id,
      value: row.id
    }, row.name))])), m(Button, {
      className: "Button Button--primary",
      disabled: !this.selected,
      onclick: () => {
        const row = this.attrs.rows.find(item => item.id === Number(this.selected));
        if (row) this.attrs.select(row);
      }
    }, "\u041F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C"));
  }
}
flarum.reg.add('maxcuso-roleplay', 'admin/catalog/components/CatalogTemplateModal', CatalogTemplateModal);