import app from 'flarum/admin/app';
export default class ApplicationSettingsApi {
  url() {
    return app.forum.attribute('apiUrl') + '/roleplay/admin/application';
  }
  async read() {
    const result = await app.request({
      method: 'GET',
      url: this.url(),
      errorHandler: () => {}
    });
    return result.data;
  }
  async save(revision, application) {
    await app.request({
      method: 'PUT',
      url: this.url(),
      body: {
        revision,
        application
      },
      errorHandler: () => {}
    });
  }
}
flarum.reg.add('maxcuso-roleplay', 'admin/application/ApplicationSettingsApi', ApplicationSettingsApi);