import app from 'flarum/admin/app';
export default class DevelopmentSettingsApi {
  url() {
    return app.forum.attribute('apiUrl') + '/roleplay/admin/development';
  }
  async read() {
    const response = await app.request({
      method: 'GET',
      url: this.url(),
      errorHandler: () => {}
    });
    return response.data;
  }
  async save(data) {
    await app.request({
      method: 'PUT',
      url: this.url(),
      body: {
        revision: data.revision,
        configuration: data.configuration
      },
      errorHandler: () => {}
    });
  }
}
flarum.reg.add('maxcuso-roleplay', 'admin/settings/development/DevelopmentSettingsApi', DevelopmentSettingsApi);