import app from 'flarum/admin/app';
/** Отправляем только иконки. Даже переименование в другом окне не будет затёрто этой формой. */
export default class AttributeIconsApi {
  url() {
    return app.forum.attribute('apiUrl') + '/roleplay/admin/attribute-icons';
  }
  async read() {
    return (await app.request({
      method: 'GET',
      url: this.url(),
      errorHandler: () => {}
    })).data;
  }
  async save(data) {
    await app.request({
      method: 'PUT',
      url: this.url(),
      body: {
        revision: data.revision,
        icons: data.rows.map(row => ({
          id: row.id,
          icon: row.icon
        }))
      },
      errorHandler: () => {}
    });
  }
}
flarum.reg.add('maxcuso-roleplay', 'admin/settings/AttributeIconsApi', AttributeIconsApi);