import { clearInputFeedback } from '../../common/messageKind';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import SettingsState from './SettingsState';
import SettingsHeader from './SettingsHeader';
import SettingsFeedback from './SettingsFeedback';
import AttributeIconsApi from './AttributeIconsApi';
import CatalogApi from '../catalog/CatalogApi';
import CatalogListState from '../catalog/CatalogListState';
import CatalogTransferModal from '../catalog/components/CatalogTransferModal';
import attributes from '../catalog/definitions/Attributes';
import showModal from '../../common/showModal';
import { catalogueIcon, uiIcon } from '../../common/uiIcons';

/** Одна строка для всех характеристик и одна атомарная операция сохранения. */
export default class AttributeIconsPanel extends Component {
  transferList = (() => new CatalogListState(new CatalogApi(attributes.endpoint)))();
  openingTransfer = false;
  active = true;
  oninit(vnode) {
    super.oninit(vnode);
    const api = new AttributeIconsApi();
    this.settings = new SettingsState(() => api.read(), data => api.save(data), () => m.redraw());
    void this.settings.load();
  }
  onremove() {
    this.active = false;
    this.settings.dispose();
    this.transferList.dispose();
  }
  async transfer(kind) {
    if (this.openingTransfer) return;
    this.openingTransfer = true;
    try {
      await this.transferList.load();
      if (!this.active) return;
      if (this.transferList.error) {
        this.settings.error = this.transferList.error;
        return;
      }
      showModal(CatalogTransferModal, {
        kind,
        definition: attributes,
        list: this.transferList,
        onImported: () => this.settings.load()
      });
    } finally {
      this.openingTransfer = false;
      m.redraw();
    }
  }
  view() {
    const state = this.settings,
      disabled = state.loading || state.saving || this.openingTransfer;
    return m("section", {
      className: "RpSettings-panel RpSettings-panel--icons"
    }, m(SettingsHeader, {
      title: "\u0418\u043A\u043E\u043D\u043A\u0438 \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440\u0438\u0441\u0442\u0438\u043A",
      icon: "fields.attribute",
      disabled: disabled,
      refresh: () => void state.load()
    }, m(Button, {
      className: "Button Button--icon",
      icon: uiIcon('actions.import'),
      title: "\u0418\u043C\u043F\u043E\u0440\u0442 JSON",
      "aria-label": "\u0418\u043C\u043F\u043E\u0440\u0442 JSON",
      disabled: disabled,
      onclick: () => void this.transfer('import')
    }), m(Button, {
      className: "Button Button--icon",
      icon: uiIcon('actions.export'),
      title: "\u042D\u043A\u0441\u043F\u043E\u0440\u0442 JSON",
      "aria-label": "\u042D\u043A\u0441\u043F\u043E\u0440\u0442 JSON",
      disabled: disabled,
      onclick: () => void this.transfer('export')
    })), m(SettingsFeedback, {
      state: state
    }), state.data && m("form", {
      oninput: () => clearInputFeedback(state),
      onchange: () => clearInputFeedback(state),
      onsubmit: event => {
        event.preventDefault();
        void state.save();
      }
    }, m("div", {
      className: "RpAttributeIcons-row"
    }, state.data.rows.map(row => m("label", {
      key: row.id,
      className: "RpSettings-field"
    }, m("span", {
      className: "RpForm-label"
    }, m(Icon, {
      name: catalogueIcon(row.icon)
    }), " ", row.name), m("input", {
      className: "FormControl",
      value: row.icon ?? '',
      maxlength: 100,
      placeholder: "fas fa-\u2026",
      disabled: disabled,
      oninput: event => {
        row.icon = event.target.value;
        state.saved = false;
      }
    }))), m(Button, {
      type: "submit",
      className: "Button Button--primary",
      icon: uiIcon('actions.save'),
      loading: state.saving,
      disabled: disabled || state.stale
    }, "\u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C"))));
  }
}
flarum.reg.add('maxcuso-roleplay', 'admin/settings/AttributeIconsPanel', AttributeIconsPanel);