import { requestMessage, requestStatus } from '../../common/requestError';

/** Общий цикл настроек: загрузка, сохранение, защита от поздних ответов и устаревшей версии. */
export default class SettingsState {
  data = null;
  loading = false;
  saving = false;
  stale = false;
  error = '';
  saved = false;
  disposed = false;
  generation = 0;
  constructor(readData, writeData, redraw) {
    this.readData = readData;
    this.writeData = writeData;
    this.redraw = redraw;
  }
  async load() {
    if (this.saving) return;
    const generation = ++this.generation;
    this.loading = true;
    this.error = '';
    this.saved = false;
    this.notify();
    try {
      const data = await this.readData();
      if (!this.disposed && generation === this.generation) {
        this.data = data;
        this.stale = false;
      }
    } catch (error) {
      if (!this.disposed && generation === this.generation) this.error = requestMessage(error, 'Не удалось загрузить настройки. Попробуйте обновить страницу');
    } finally {
      if (generation === this.generation) {
        this.loading = false;
        this.notify();
      }
    }
  }
  async save() {
    if (!this.data || this.loading || this.saving || this.stale) return;
    this.saving = true;
    this.saved = false;
    this.error = '';
    this.notify();
    // Вход формы может изменяться во время запроса. Отправляем неизменяемую копию.
    const submitted = JSON.parse(JSON.stringify(this.data));
    try {
      await this.writeData(submitted);
      const data = await this.readData();
      if (!this.disposed) {
        this.data = data;
        this.saved = true;
      }
    } catch (error) {
      if (!this.disposed) {
        this.error = requestMessage(error, 'Не удалось сохранить настройки. Попробуйте обновить страницу');
        const status = requestStatus(error);
        this.stale = status === 409 || status === undefined || status === 0 || status >= 500;
      }
    } finally {
      this.saving = false;
      this.notify();
    }
  }
  dispose() {
    this.disposed = true;
    this.generation++;
  }
  notify() {
    if (!this.disposed) this.redraw();
  }
}
flarum.reg.add('maxcuso-roleplay', 'admin/settings/SettingsState', SettingsState);