/** Данные справочников используются в админке, мастере и профиле. Здесь нет зависимости от экранов. */

export function text(row, field) {
  return String(row[field] ?? '');
}
export function number(row, field) {
  return Number(row[field] ?? 0);
}
export function object(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value) ? value : {};
}
export function ids(value) {
  return Array.isArray(value) ? value.map(Number) : [];
}
export function lookup(lookups, key, id) {
  return (lookups[key] ?? []).find(row => row.id === Number(id));
}
export function options(lookups, key, useSlug) {
  if (useSlug === void 0) {
    useSlug = false;
  }
  return Object.fromEntries((lookups[key] ?? []).map(row => [useSlug ? text(row, 'slug') : String(row.id), row.name + (row.enabled === false ? ' (выключено)' : '')]));
}
flarum.reg.add('maxcuso-roleplay', 'common/catalogData', { text: text,number: number,object: object,ids: ids,lookup: lookup,options: options, });